{
  "name": "串口通信组件",
  "name_en": "Serial Port Communication Helper",
  "manufacturer": "",
  "description": "这是一个非物理的软件通信组件，用于封装串口连接的启动、停止、缓冲区清理，以及按字节、字符串或整行进行读写。它主要用于实验系统与外部仪器、控制器或微控制器之间的串行数据交换，并提供异常处理以及字节与字符串之间的编码/解码支持。",
  "description_en": "This is a non-physical software communication component that wraps serial port connection start/stop, buffer clearing, and byte-, string-, or line-based read/write operations. It is used to exchange serial data between a lab system and external instruments, controllers, or microcontrollers, while providing exception handling and byte/string encoding-decoding support.",
  "actions": [
    {
      "action_name": "auto-start",
      "description": "启动串口通信会话。",
      "description_en": "Start the serial communication session."
    },
    {
      "action_name": "auto-stop",
      "description": "停止串口通信会话。",
      "description_en": "Stop the serial communication session."
    },
    {
      "action_name": "auto-buffered",
      "description": "查询当前串口接收缓冲区中的可读字符数量。",
      "description_en": "Query the number of readable characters currently buffered in the serial receive buffer."
    },
    {
      "action_name": "auto-clear",
      "description": "清空串口读取缓冲区。",
      "description_en": "Clear the serial read buffer."
    },
    {
      "action_name": "auto-readBytes",
      "description": "按指定字节数从串口读取原始字节数据。",
      "description_en": "Read raw byte data from the serial port by the requested byte count."
    },
    {
      "action_name": "auto-read",
      "description": "按指定长度从串口读取并解码为字符串。",
      "description_en": "Read data from the serial port by the requested length and decode it as text."
    },
    {
      "action_name": "auto-readln",
      "description": "从串口读取一整行文本，直到行结束符。",
      "description_en": "Read a full line of text from the serial port until the end-of-line marker."
    },
    {
      "action_name": "auto-writeBytes",
      "description": "向串口写入原始字节数据。",
      "description_en": "Write raw byte data to the serial port."
    },
    {
      "action_name": "auto-write",
      "description": "向串口写入字符串数据。",
      "description_en": "Write string data to the serial port."
    },
    {
      "action_name": "auto-writeln",
      "description": "向串口写入一行文本数据。",
      "description_en": "Write a line of text data to the serial port."
    }
  ],
  "tag_hints": [
    "serial communication",
    "RS-232/USB serial",
    "buffered I/O",
    "line-oriented reading",
    "instrument integration",
    "byte-string encoding",
    "communication helper",
    "testing and mocking"
  ]
}

